// HARNESS DB TEST (ARCHETYPE_DB_TESTS=1) — runs databases/postgres.md's RLS snippet against a real
// postgres: with FORCE ROW LEVEL SECURITY and the doc's policy, a non-superuser sees only the tenant
// that set_config set, the setting ends with the transaction, and the old SET LOCAL ... = $1 form is
// rejected by Postgres.
import (
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"github.com/testcontainers/testcontainers-go/modules/postgres"
)

const (
	tenantA = "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"
	tenantB = "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb"
)

func TestSetTenantContext_RLSScopesRows(t *testing.T) {
	ctx := context.Background()
	pg, err := postgres.Run(ctx, "postgres:16-alpine", postgres.BasicWaitStrategies())
	require.NoError(t, err)
	t.Cleanup(func() { _ = pg.Terminate(ctx) })
	dsn, err := pg.ConnectionString(ctx, "sslmode=disable")
	require.NoError(t, err)
	pool, err := pgxpool.New(ctx, dsn)
	require.NoError(t, err)
	t.Cleanup(pool.Close)

	// The policy is postgres.md's (Row-Level Security); the role is how the app connects: no
	// superuser, no BYPASSRLS — RLS does not apply to superusers.
	_, err = pool.Exec(ctx, `
		CREATE ROLE app_user NOSUPERUSER NOBYPASSRLS;
		CREATE TABLE widgets (id serial PRIMARY KEY, tenant_id uuid NOT NULL, name text NOT NULL);
		ALTER TABLE widgets ENABLE ROW LEVEL SECURITY;
		ALTER TABLE widgets FORCE ROW LEVEL SECURITY;
		CREATE POLICY tenant_isolation ON widgets
		    USING (tenant_id = current_setting('app.current_tenant_id')::uuid);
		GRANT SELECT ON widgets TO app_user;
		INSERT INTO widgets (tenant_id, name) VALUES
		    ('`+tenantA+`', 'a1'), ('`+tenantA+`', 'a2'), ('`+tenantB+`', 'b1');`)
	require.NoError(t, err)

	visible := func(tenantID string) []string {
		var names []string
		err := pgx.BeginFunc(ctx, pool, func(tx pgx.Tx) error {
			if _, err := tx.Exec(ctx, "SET LOCAL ROLE app_user"); err != nil {
				return err
			}
			if err := setTenantContext(ctx, tx, tenantID); err != nil { // the doc's snippet
				return err
			}
			rows, err := tx.Query(ctx, "SELECT name FROM widgets ORDER BY name")
			if err != nil {
				return err
			}
			names, err = pgx.CollectRows(rows, pgx.RowTo[string])
			return err
		})
		require.NoError(t, err)
		return names
	}
	assert.Equal(t, []string{"a1", "a2"}, visible(tenantA))
	assert.Equal(t, []string{"b1"}, visible(tenantB))

	// is_local=true: the setting ends with the transaction
	var after string
	require.NoError(t, pool.QueryRow(ctx, "SELECT coalesce(current_setting('app.current_tenant_id', true), '')").Scan(&after))
	assert.Equal(t, "", after)

	// The form the doc used before: SET takes no bind parameters, so Postgres rejects it (42601)
	err = pgx.BeginFunc(ctx, pool, func(tx pgx.Tx) error {
		_, err := tx.Exec(ctx, "SET LOCAL app.current_tenant_id = $1", tenantA)
		return err
	})
	var pgErr *pgconn.PgError
	require.ErrorAs(t, err, &pgErr)
	assert.Equal(t, "42601", pgErr.Code)
}

