// HARNESS SMOKE TEST — drives frameworks/chi.md's router: a malformed id is a 400 envelope, a
// found user is the {data, meta.request_id} envelope, and RequireTenant without a verified identity
// is a 401 envelope.
import (
	"github.com/google/uuid"

	"yourapp/internal/middleware"
)

type fakeUsers struct{}

func (fakeUsers) Get(ctx context.Context, id uuid.UUID) (*User, error) {
	return &User{ID: id, Email: "a@example.com"}, nil
}

func passthrough(next http.Handler) http.Handler { return next }

func decode(t *testing.T, rec *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	var m map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &m); err != nil {
		t.Fatalf("body %q: %v", rec.Body.String(), err)
	}
	return m
}

func TestChiRouterEnvelopes(t *testing.T) {
	r := NewRouter(&Handlers{h: &Handler{service: fakeUsers{}}},
		&Middleware{Logger: passthrough, Auth: passthrough}, slog.New(slog.DiscardHandler))

	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/api/v1/users/not-a-uuid/", nil))
