type Widget struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Status string `json:"status"`
}

type WidgetClient struct{ baseURL string }

func NewWidgetClient(baseURL string) *WidgetClient { return &WidgetClient{baseURL: baseURL} }

func (c *WidgetClient) GetWidget(id string) (*Widget, error) {
	req, err := http.NewRequest(http.MethodGet, c.baseURL+"/api/v1/widgets/"+url.PathEscape(id), nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Authorization", "Bearer dashboard-token")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("get widget: status %d", resp.StatusCode)
	}
	var body struct {
		Data Widget `json:"data"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		return nil, err
	}
	return &body.Data, nil
}

var (
	widgetsMu sync.Mutex
	widgets   = map[string]Widget{}
)

func seedWidget(id, name, status string) {
	widgetsMu.Lock()
	defer widgetsMu.Unlock()
	widgets[id] = Widget{ID: id, Name: name, Status: status}
}

func startTestServer() *httptest.Server {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /api/v1/widgets/{id}", func(w http.ResponseWriter, r *http.Request) {
		widgetsMu.Lock()
		wd, ok := widgets[r.PathValue("id")]
		widgetsMu.Unlock()
		w.Header().Set("Content-Type", "application/json")
		if !ok {
			w.WriteHeader(http.StatusNotFound)
			_, _ = w.Write([]byte(`{"error":{"code":"NOT_FOUND","message":"Widget not found.","request_id":"req-1","retryable":false}}`))
			return
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"data": wd, "meta": map[string]any{"request_id": "req-1"}})
	})
	return httptest.NewServer(mux)
}
